def linear_search(items, target):
    for i, value in enumerate(items):
        if value == target:
            return i
    return -1

def bubble_sort(items):
    for i in range(len(items) - 1):
        for j in range(len(items) - 1 - i):
            if items[j] > items[j + 1]:
                items[j], items[j + 1] = items[j + 1], items[j]
    return items

